INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 11, 'theory', 'Quiz: real time');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 0, 'How does a WebSocket differ from an ordinary HTTP request?', '["It works without a network", "After the handshake the connection stays open and both sides can send data at any moment", "It needs no server", "It is always faster"]', 1, 'It is a long-lived two-way connection; the resource becomes the number of open connections.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 1, 'What is the main resource when scaling WebSocket gateways?', '["Disk speed", "The number of simultaneously open connections: descriptors and memory", "Database size", "DNS bandwidth"]', 1, 'One gateway holds tens of thousands of connections; gateways are scaled by their number.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 2, 'How do you avoid a connection storm after a gateway fails?', '["Do nothing", "Clients reconnect with a growing pause and random jitter, and gateways limit the accept rate", "Disconnect all clients", "Forbid reconnecting"]', 1, 'Otherwise all clients rush the remaining gateways at the same time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 3, 'How is the “online” status stored?', '["In the main database, written on every change", "In a fast cache with a short TTL refreshed by heartbeats", "In the server log", "In the browser"]', 1, 'The record expires when the heartbeat stops; accuracy down to the second is not needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 4, 'How does a client restore its history after reconnecting?', '["Reloads everything from scratch", "Reports the number of the last message received, and the server sends the missed ones", "Waits for a new message", "It does not restore it"]', 1, 'The chat number sets the order; catching up from the last number loses no messages.');
